function bitsAlternate(n: number): boolean {
  let prev = n & 1;
  n >>>= 1;
  while (n > 0) {
    const bit = n & 1;
    if (bit === prev) return false;
    prev = bit;
    n >>>= 1;
  }
  return true;
}

